  if (isMFARequired(e)) {
    const {mfa_token} = e.response.data;
    // Collect a code from the user, then:
    const {access_token} = await authenticate(VerdocsEndpoint.getDefault(), {
      grant_type: 'urn:verdocs:params:oauth:grant-type:mfa-otp', mfa_token, otp});
  }
}

